import re
from functools import partial


def sorting_key(string):
    return ''.join([format(int(x), '05d') if x.isdigit() else x for x in re.split(r'(\d+)', string)])


class DistNameGenerator:

    def __init__(self, pddb_params, pddb_topology, enb_ent_config, nr=False):
        self.pddb_params = pddb_params
        self.pddb_topology = pddb_topology
        self.enb_ent_config = enb_ent_config
        self.nr = nr
        self.setup_nr()

    def setup_nr(self):
        if self.nr:
            if 'CHANNELGROUP' in self.pddb_topology:
                self.pddb_topology['CHANNELGROUP']['parent'] = 'LCELNR'

    def get_mandatory_children(self, parent='MRBTS'):
        mandatory_children = [
            k for k, v in self.pddb_topology.items()
            if v['parent'] == parent and v['mo_min_occurs'] != '0' and not k.endswith('_R')
        ]
        return mandatory_children

    def generate_dist_names(self):
        tree = {0: [f'MRBTS-{self.enb_ent_config["id"]}']}
        current_level = 0
        go_to_next_level = True
        while go_to_next_level:
            tree[current_level + 1] = []
            go_to_next_level = False
            branch_domain = None

            for branch in tree[current_level]:
                parent = branch.split('/')[-1].split('-')[0] if '/' in branch else branch.split('-')[0]
                children = self.get_mandatory_children(parent)

                branch_domain = self.get_branch_domain(branch)
                filter_func = partial(self.filter_wrong_domain_children, branch_domain=branch_domain)
                children = list(filter(filter_func, children))

                if children and not go_to_next_level:
                    go_to_next_level = True

                for child in children:
                    starting_index = self.get_starting_index(child)
                    occurrences = self.get_mo_occurrences(child)
                    for occurrence in range(starting_index, starting_index + occurrences):
                        tree[current_level + 1].append(branch + f'/{child}-{occurrence}')
            current_level += 1

        return [v for value in tree.values() for v in value if value]

    def get_branch_domain(self, branch):
        cel_number = re.search(r'/LNCEL-(\d+)', branch)
        if not cel_number:
            cel_number = re.search(r'/NRCELL-(\d+)', branch)
            if not cel_number:
                return None

        cell_number = cel_number.group(1)
        if self.enb_ent_config['cells'][cell_number]['is_fdd']:
            return 'FDD'
        return 'TDD'

    def get_starting_index(self, managed_object):
        index_name = self.pddb_topology[managed_object]['index']
        index = self.pddb_params[managed_object][index_name]['range']
        if isinstance(index, list):
            min_index_value = int(index.pop(0))
        else:
            min_index_value = int(index)
        return min_index_value

    def get_mo_occurrences(self, managed_object):
        mo_min_occurs = self.pddb_topology[managed_object]['mo_min_occurs']
        if isinstance(mo_min_occurs, list):
            occurrences = int(mo_min_occurs.pop(0))
        else:
            occurrences = int(mo_min_occurs)
        return occurrences

    @staticmethod
    def filter_wrong_domain_children(child, branch_domain):
        if branch_domain == 'FDD' and re.search(r'tdd', child, re.I):
            return False
        if branch_domain == 'TDD' and re.search(r'fdd', child, re.I):
            return False
        return True
